CREATE TABLE viewer_manifest(scan_id uuid PRIMARY KEY REFERENCES scan_import(id),object_id uuid NOT NULL REFERENCES storage_version(id),object_hash text NOT NULL CHECK(object_hash~'^[a-f0-9]{64}$'),scan_version bigint NOT NULL,provider text NOT NULL CHECK(provider='SYN-RGB-PYRAMID-1'),manifest_hash text NOT NULL CHECK(manifest_hash~'^[a-f0-9]{64}$'),manifest jsonb NOT NULL CHECK(jsonb_typeof(manifest)='object'),created_by uuid NOT NULL REFERENCES app_user(id),created_at timestamptz NOT NULL DEFAULT statement_timestamp());
CREATE FUNCTION check_viewer_binding() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM scan_import s WHERE s.id=NEW.scan_id AND s.object_id=NEW.object_id AND s.object_hash=NEW.object_hash AND s.version=NEW.scan_version AND s.state='PENDING_DIGITAL_QC') THEN RAISE EXCEPTION 'Viewer source mismatch' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER trg_viewer_binding BEFORE INSERT ON viewer_manifest FOR EACH ROW EXECUTE FUNCTION check_viewer_binding();
CREATE TRIGGER trg_viewer_immutable BEFORE UPDATE OR DELETE ON viewer_manifest FOR EACH ROW EXECUTE FUNCTION protect_gross_append_only();
CREATE TABLE viewer_read_budget(user_id uuid NOT NULL REFERENCES app_user(id),minute timestamptz NOT NULL,requests integer NOT NULL CHECK(requests BETWEEN 0 AND 240),bytes bigint NOT NULL CHECK(bytes BETWEEN 0 AND 33554432),PRIMARY KEY(user_id,minute));
